head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[column > P > allOption]<br/>Column 의 SelectBox 에 '전체 선택'을 의미하는 아이템의 추가 여부를 설정합니다.",
    "validation" : [
        "Column 의 inputType='select' 인 경우에 동작합니다.",
        "true 설정 시, '전체 선택'을 의미하는 아이템을 자동으로 추가합니다.",
        "true 설정 시, 아이템의 Label 값은 '전체 선택', Value 값은 'all' 로 설정됩니다.",
        "false 설정 시, Column 에 아이템을 추가하지 않습니다.",
        "미설정 시, Column 에 아이템을 추가하지 않습니다.",
        "'전체 선택' 아이템은 아이템 리스트에 첫번째 아이템으로 추가되며 0 번 인덱스값을 갖습니다.",
        "'전체 선택' 아이템이 선택된 상태에서 다른 아이템의 선택이 한 개라도 해제되면 '전체 선택' 아이템의 선택 상태도 해제됩니다.",
        "일반 아이템이 모두 선택되면 '전체 선택' 아이템이 자동으로 선택됩니다.",
        "'전체 선택' 아이템의 Value, Label 값은 선택 아이템에 포함되지 않습니다.",
        "'전체 선택' 아이템의 Label 값은 변경할 수 없습니다.",
    ]
}



scwin.onpageload = async function () {
    // Global DataList(gdl_boolean 등) 생성 호출
    $c.gcm.createCommonDatalist();

    // 정적 select1 은 초기 selectedIndex 가 적용되지 않으므로 기본값 명시 설정 (gdl_boolean 코드 "2" = true)
    con_allOption.setValue("2");
    con_allOptionLabel.setValue("");

    // comp 초기 생성
    await scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
//  - name   : 비교용 text Column
//  - region : 검증 대상 Column (inputType=select, 아이템 서울(S) / 부산(B) / 대구(D) 정적 정의, allOption 을 옵션값으로 설정)
scwin.comp_init = async function () {
    // 기존 target / dataList / label 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof label1 !== 'undefined' && label1) {
        label1.remove();
    }

    // 조건 설정 (gdl_boolean 은 getText() 로 '' / 'true' / 'false' 판단)
    let cAllOption = con_allOption.getText();
    let cAllOptionLabel = con_allOptionLabel.getValue();

    // 테스트 정보 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] 검증 대상은 region Column (inputType=select, 아이템 : 서울(S) / 부산(B) / 대구(D)), Label 변경 시도는 Column 에 allOptionLabel 속성을 설정\n[절차] Row 0 region 셀 더블클릭 -> 목록에서 아이템 선택 -> allOption 확인\n[확인] 아이템 리스트의 0 번 아이템과 선택 후 셀 값을 확인"', '', 'label1');

    // dataList 생성 (body column id 와 동일한 컬럼 id 사용)
    let strNameSpace = $c.gcm.getNameSpace();
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="region" name="region" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);
    dlt_bind.setJSON([
        { "name" : "홍길동", "region" : "S" },
        { "name" : "김철수", "region" : "B" },
        { "name" : "이영희", "region" : "D" }
    ], false);

    // region Column 속성 (미설정 옵션은 속성 자체를 넣지 않는다)
    let attrRegion = ' inputType="select"';
    if (cAllOption !== '') {
        attrRegion += ' allOption="' + cAllOption + '"';
    }
    if (cAllOptionLabel !== '') {
        attrRegion += ' allOptionLabel="' + cAllOptionLabel + '"';
    }

    // 정적 아이템
    let strItems = '';
    strItems += '<w2:choices>';
    strItems += '<w2:item><w2:label>서울</w2:label><w2:value>S</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>부산</w2:label><w2:value>B</w2:value></w2:item>';
    strItems += '<w2:item><w2:label>대구</w2:label><w2:value>D</w2:value></w2:item>';
    strItems += '</w2:choices>';

    // target 생성
    let grp_comp = $c.gcm.getTestGroup();
    let strTarget = '';

    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" checkAllType="false" id="" style="width:500px;height:150px;">';
    strTarget += '<w2:caption style="" id="caption1" value="this is a grid caption."></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="column1" value="name"></w2:column>';
    strTarget += '<w2:column width="300" style="" inputType="text" id="column2" value="region (select)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" value=""></w2:column>';
    strTarget += '<w2:column width="300" style="" id="region" value=""' + attrRegion + '>' + strItems + '</w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin["target1"] = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );
}



// Row 0 region 셀의 아이템 리스트 / 셀 값 확인 (inputType=select 고정)
//  - validation 1 : select Column 편집기의 아이템 리스트 출력
//  - validation 2, 3, 6, 10 : 아이템 리스트 [0] 의 Label (Value)
//  - validation 4, 5 : 아이템 리스트에 추가 아이템 없음
//  - validation 7, 8 : 단일 선택이라 셀 값이 항상 1개 (전체 선택 선택 후 다른 아이템 선택 시 해당 아이템 1개로 교체, 자동 선택 없음)
//  - validation 9 : 셀 값(getCellData) 과 셀 표시값에 all / 전체 선택 Label 포함 여부
scwin.btn_checkAllOption_onclick = function () {
    let bottom = wf_body_bottom.getObj("scwin");

    // 셀 편집 시 생성되는 region Column 의 선택 아이템 편집기 (selectbox)
    let editor = $p.getComponentById("G_" + target1.id + "___selectbox_region");

    if (!editor) {
        bottom.setReturnValue("아이템 리스트 : 선택 아이템 편집기 미생성");
    } else {
        let arrItem = editor.getItemArray().map(function (item, idx) {
            return "[" + idx + "] " + item.label + " (" + item.value + ")";
        });
        bottom.setReturnValue("아이템 리스트 : " + arrItem.join(" / "));
    }

    let cellData = target1.getCellData(0, "region");
    let td = document.querySelector("td[id*='target1_cell_0_1']");
    let cellText = td ? td.textContent : "";
    bottom.setReturnValue("Row 0 셀 값(getCellData) : " + (cellData === "" ? "(빈 값)" : cellData) + " / 셀 표시값 : " + (cellText === "" ? "(빈 값)" : cellText));
}
